import { Container, Graphics, PointData, Sprite, Text, Texture } from 'pixi.js';
import gsap from 'gsap';

import { AssetManager } from '@game-studio/asset-manager';

import { CabinetButtonView } from './cabinet-button';
import { mainTextStyle, stakeTextStyle } from '../../layout/text-style';
import { AnimationSpeed, CabinetButtonTextPositions, CabinetLayoutState, ICabinetButtonTextConfig, ICabinetConfig, IPointerEvent } from '../../types/cabinet';
import { LoadingSpinner } from '../auto-play/loading-spinner';

export class ActionButtonView extends CabinetButtonView {
    private mode: CabinetLayoutState;
    private state: 'enabled' | 'disabled' = 'enabled';
    
    private stakeText: Text;
    private mainText: Text;
    
    private buttonMask: Graphics;
    
    private stakeChangeTimeline: gsap.core.Timeline | undefined;
    private scaleTween: gsap.core.Tween | undefined;
    private spritePositionTween: gsap.core.Tween | gsap.core.Timeline | undefined;
    private textAlphaTween: gsap.core.Tween | undefined;
    private tweenHeightMultiplier: number = 1.5;
    
    private loadingSpinner: LoadingSpinner;
    private spinnerDelay: number = 500;
    private loadingSpinnerTimer: number;
    
    private spriteYOffsets = { enabled: 0, disabled: 0 };
    private scales = { enabled: 1, disabled: 0.5 };

    private canHideTextOnDisabled = false;
    private get shouldAnimateDisabled(): boolean {
        return this.mode === 'anchored';
    }

    constructor(mode: CabinetLayoutState, buttonTexture: Texture, pointerup?: IPointerEvent[]) {
        super(buttonTexture, pointerup);

        this.createStakeText();
        this.createMainText();
        this.createButtonMask();
        this.createLoadingSpinner();

        const sheen = new Sprite(AssetManager.getTexture('action-button-sheen'));
        sheen.anchor.set(0.5);
        this.buttonSprite.addChild(sheen);

        this.setMode(mode);
        this.updateMask();
    }

    public get buttonSpriteHeight(): number { return this.buttonSprite.height * this.scale.y; }
    public get defaultScaledWidth(): number { return this.dimensions.width * this.scales.enabled; }

    public set showStake(value: boolean) { this.stakeText.visible = value; }
    public set loadingSpinnerDelay(delay: number) { this.spinnerDelay = Math.round(delay * 1000); }
    public set holdSpinnerDuration(duration: number) { this.loadingSpinner.holdAnimationDuration = duration; }

    public set showLoadingSpinner(value: boolean) {
        window.clearTimeout(this.loadingSpinnerTimer);

        if (value) {
            this.loadingSpinnerTimer = window.setTimeout(() => {
                this.loadingSpinner.alpha = 1;
                this.loadingSpinner.animateLoading();
            }, this.spinnerDelay);
        } else {
            this.loadingSpinner.alpha = 0;
            this.loadingSpinner.killTweens();
        }
    }

    public set showActionHoldSpinner(value: boolean) {
        window.clearTimeout(this.loadingSpinnerTimer);

        if (value) {
            this.loadingSpinner.animateHold();
            this.loadingSpinner.alpha = 1;
        } else {
            this.loadingSpinner.alpha = 0;
            this.loadingSpinner.killTweens();
        }
    }

    public enable(value: boolean, canAnimate: boolean = true): void {
        this.setState(value ? 'enabled' : 'disabled', canAnimate);
    }

    public enterFreePlay(config: ICabinetButtonTextConfig): void {
        this.updateMainText(config.message, config.position, config.fontSize);
        this.updateStakeText('');
    }

    public updateScale(scale: number, disabledScale?: number): void {
        this.scaleTween?.kill();

        this.scales = {
            enabled: scale,
            disabled: disabledScale ?? scale
        };

        if (this.state === 'disabled' && this.shouldAnimateDisabled) {
            this.scale.set(this.scales.disabled);
        } else {
            this.scale.set(this.scales.enabled);
        }

        this.updateMask();
    }

    public updateMainText(text: string, position: CabinetButtonTextPositions, fontSize: number): void {
        mainTextStyle.fontSize = fontSize;

        this.mainText.style = mainTextStyle;

        this.updateMainTextBox(text, position);
    }

    public async updateStakeText(text: string): Promise<void> {
        this.stakeChangeTimeline?.kill();

        this.stakeChangeTimeline = gsap.timeline({
            onStart: () => { this.addMask(); },
            onComplete: () => { this.removeMask(); }
        });
        
        const duration = AnimationSpeed.stakeText;
        const distance = this.buttonSprite.height * this.tweenHeightMultiplier;

        this.stakeChangeTimeline.to(this.stakeText, { duration, y: distance });
        this.stakeChangeTimeline.call(() => this.updateStakeTextBox(text));
        this.stakeChangeTimeline.set(this.stakeText, { y: -distance });
        this.stakeChangeTimeline.to(this.stakeText, { duration, y: this.buttonSprite.height * 0.125 });
    }

    public bounce(): void {
        this.spritePositionTween?.progress(1).kill();

        const bounces = 2;
        const bounceHeight = 0.3;
        const duration = 0.175;
        const initialY = this.buttonSprite.position.y;

        this.spritePositionTween = gsap.timeline();

        for (let i = 0; i < bounces; i++) {
            this.spritePositionTween.to([this.buttonSprite, this.loadingSpinner], { duration, y: -this.buttonSprite.height * bounceHeight, ease: 'Power0.in' });
            this.spritePositionTween.to([this.buttonSprite, this.loadingSpinner], { duration, y: initialY, ease: 'bounce.out' });
        }
    }

    public updateMainTextStyle(config: ICabinetConfig): void {
        mainTextStyle.fill = config.text.buyButton.colour;
        mainTextStyle.fontFamily = config.text.buyButton.font;

        stakeTextStyle.fill = config.text.buyButton.colour;
        stakeTextStyle.fontSize = config.text.buyButton.stakeFontSize;
        stakeTextStyle.fontFamily = config.text.buyButton.font;

        this.stakeText.style = stakeTextStyle;
        this.mainText.style = mainTextStyle;
    }

    private setState(state: 'enabled' | 'disabled', canAnimate: boolean = true): void {
        this.scaleTween?.kill();
        this.spritePositionTween?.kill();
        this.textAlphaTween?.kill();

        this.state = state;
        const isEnabled = state === 'enabled';
        this.interactionEnabled = isEnabled;

        this.buttonSprite.alpha = isEnabled ? 1 : 0.6;

        if (canAnimate && this.shouldAnimateDisabled) {
            const scale = this.scales[state];

            const duration = 0.3;
            this.scaleTween = gsap.to(this.scale, { duration, x: scale, y: scale });
            this.spritePositionTween = gsap.to([this.buttonSprite, this.loadingSpinner], { duration, y: this.spriteYOffsets[state] });
            if (this.canHideTextOnDisabled) {
                this.textAlphaTween = gsap.to([this.mainText, this.stakeText], { duration, alpha: isEnabled ? 1 : 0 });
            }
        }
    }

    public setMode(mode: CabinetLayoutState): void {
        this.mode = mode;

        if (this.canHideTextOnDisabled) {
            if (this.mode === 'floating' || this.state === 'enabled') {
                this.mainText.alpha = this.stakeText.alpha = 1;
            } else {
                this.mainText.alpha = this.stakeText.alpha = 0;
            }
        }
    }

    public onOrientationChange(): void {
        this.scaleTween?.progress(1).kill();
        this.spritePositionTween?.progress(1).kill();
        this.textAlphaTween?.progress(1).kill();
        this.stakeChangeTimeline?.progress(1, false).kill();
    }

    public updateYOffset(point: PointData, from: Container): void {
        // Get the local point at the current scale
        const offset = this.toLocal(point, from);

        // Adjust for the difference between current scale and enabled scale
        const scaleRatio = this.scale.x / this.scales.enabled;
        const adjustedY = offset.y * scaleRatio;

        if (this.mode === 'floating') {
            this.spriteYOffsets.enabled = 0;
            this.spriteYOffsets.disabled = 0;
        } else {
            this.spriteYOffsets.enabled = adjustedY - this.dimensions.height * 0.45;
            this.spriteYOffsets.disabled = 0;
        }

        this.buttonSprite.position.y = this.spriteYOffsets[this.state];
        this.loadingSpinner.position.y = this.buttonSprite.position.y;
    }

    private updateMask() {
        // Redraw mask to fit new button texture
        const buttonRadius = Math.min(this.buttonSprite.width, this.buttonSprite.height) * 0.5;
        this.buttonMask.clear();
        this.buttonMask.beginFill(0xFFFFFF);
        this.buttonMask.drawCircle(0, 0, buttonRadius);
        this.buttonMask.endFill();
    }

    private createStakeText(): void {
        this.stakeText = new Text('', stakeTextStyle);

        this.buttonSprite.addChild(this.stakeText);
    }

    private createMainText(): void {
        this.mainText = new Text('', stakeTextStyle);
        this.mainText.anchor.set(0.5);

        this.buttonSprite.addChild(this.mainText);
    }

    private createButtonMask(): void {
        const buttonRadius = Math.min(this.buttonSprite.width, this.buttonSprite.height) * 0.5;

        this.buttonMask = new Graphics();
        this.buttonMask.beginFill(0xFFFFFF);
        this.buttonMask.drawCircle(0, 0, buttonRadius);
        this.buttonMask.endFill();
    }

    private createLoadingSpinner(): void {
        this.loadingSpinner = new LoadingSpinner(this.buttonSprite.width, this.buttonSprite.height);
        this.loadingSpinner.alpha = 0;

        this.addChild(this.loadingSpinner);
    }

    private updateStakeTextBox(text: string): void {
        this.stakeText.text = text;
        this.stakeText.anchor.set(0.5);

        this.scaleTextToFit();
    }

    private updateMainTextBox(text: string, position: CabinetButtonTextPositions): void {
        this.mainText.text = text;
        this.mainText.anchor.set(0.5);

        switch (position) {
            case 'top':
                this.mainText.position.y = -this.buttonSprite.height * 0.2;
                break;
            case 'middle':
                this.mainText.position.y = 0;
                break;
            case 'bottom':
            default:
                this.mainText.position.y = this.buttonSprite.height * 0.2;
                break;
        }

        this.scaleTextToFit();
    }

    private scaleTextToFit(): void {
        // Calculate available space within the circular button
        const buttonRadius = Math.min(this.buttonSprite.width, this.buttonSprite.height) * 0.5;
        const availableWidth = buttonRadius * 1.6; // Slightly smaller than diameter for padding
        const availableHeight = buttonRadius * 1.6;

        this.scaleStakeText(availableWidth, availableHeight);
        this.scaleMainText(availableWidth, availableHeight);
    }

    private scaleStakeText(availableWidth: number, availableHeight: number): void {
        this.stakeText.scale.set(1);

        const widthScale = availableWidth / this.stakeText.width;
        const heightScale = availableHeight / this.stakeText.height;
        const scale = Math.min(widthScale, heightScale, 1.5);

        this.stakeText.scale.set(scale);
    }

    private scaleMainText(availableWidth: number, availableHeight: number): void {
        this.mainText.scale.set(1);

        // For main text, consider the space it shares with stake text
        const availableMainTextHeight = this.stakeText.visible ? availableHeight * 0.6 : availableHeight;

        const widthScale = availableWidth / this.mainText.width;
        const heightScale = availableMainTextHeight / this.mainText.height;
        const scale = Math.min(widthScale, heightScale, 1.5);

        this.mainText.scale.set(scale);
    }

    private addMask(): void {
        this.buttonSprite.addChild(this.buttonMask);
        this.stakeText.mask = this.buttonMask;
        this.mainText.mask = this.buttonMask;
    }

    private removeMask(): void {
        this.stakeText.mask = null;
        this.mainText.mask = null;
        this.buttonSprite.removeChild(this.buttonMask);
    }
}